long long fast_pow(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = res * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return res;
}

vector<int> find_relation(const vector<int>& seq) {
    vector<int> relation, current;
    int last_pos, delta;
    for (int i = 0; i < (int)seq.size(); ++i) {
        long long t = 0;
        for (int j = 0; j < (int)current.size(); ++j)
            t = (t + seq[i - j - 1] * (long long)current[j]) % 998244353;
        if ((t - seq[i]) % 998244353 == 0) continue;
        if (current.empty()) {
            current.resize(i + 1);
            last_pos = i;
            delta = (t - seq[i]) % 998244353;
            continue;
        }
        long long k = - (seq[i] - t) * fast_pow(delta, 998244351, 998244353) % 998244353;
        vector<int> c(i - last_pos - 1, 0);
        c.push_back(k);
        for (int j = 0; j < (int)relation.size(); ++j)
            c.push_back(-relation[j] * k % 998244353);
        if ((int)c.size() < (int)current.size()) c.resize(current.size());
        for (int j = 0; j < (int)current.size(); ++j)
            c[j] = (c[j] + current[j]) % 998244353;
        if (i - last_pos + (int)relation.size() >= (int)current.size()) {
            relation = current;
            last_pos = i;
            delta = (t - seq[i]) % 998244353;
        }
        current = c;
    }
    for (int& x : current) x = (x % 998244353 + 998244353) % 998244353;
    return current;
}

int main() {
