    cin.tie(nullptr);
    long long n;
    cin >> n;
    n++;
    const long long MOD = 998244353;
    const long long MOD1 = 1000000007;
    long long up = n;
    long long part = (n % MOD) * ((n / MOD1) + 2) % MOD;
    part = MOD - part;

    long long total = 0;
    for (long long i = -n / MOD1 - 1; i <= n / MOD1 + 1; ++i) {
        long long sum_curr = 0;
